{
  "taxClaims": [
    {
      "text": "If tax clearance is required for your employee, you must file the Form IR21 at least one month before:\n\nThe employee ceases to work for you in Singapore;",
      "recordId": "LIVE_TOPIC_iras-employer-ir21_8b2fd2a8dc37",
      "quote": "If tax clearance is required for your employee, you must file the Form IR21 at least one month before:\n\nThe employee ceases to work for you in Singapore;",
      "kind": "RULE"
    },
    {
      "text": "Generally, when your non-Singapore Citizen employee ceases employment with you in Singapore, goes on an overseas posting or plans to leave Singapore for more than three months, you must notify IRAS at least one month in advance and withhold all monies due to the employee from the date you are aware of his impending cessation of employment or departure from Singapore.",
      "recordId": "LIVE_TOPIC_iras-employer-ir21_8b2fd2a8dc37",
      "quote": "Generally, when your non-Singapore Citizen employee ceases employment with you in Singapore, goes on an overseas posting or plans to leave Singapore for more than three months, you must notify IRAS at least one month in advance and withhold all monies due to the employee from the date you are aware of his impending cessation of employment or departure from Singapore.",
      "kind": "RULE"
    }
  ],
  "treatment": "",
  "requiredAccounts": []
}

